// Generated by `just generate` from `src/plugins/claudetto/slices/minispec/domain/spec.ts`. Edit the source and run `just generate`.
// The requirements of a spec, the deltas of a change, and the merge of a delta into a spec (spec `minispec`, "Archive").
// A spec file has `## Purpose` and `## Requirements`, and each requirement is a block `### Requirement: <name>` with `#### Scenario: <name>` blocks.
// A delta file has the sections `## ADDED Requirements`, `## MODIFIED Requirements`, and `## REMOVED Requirements`.
// The functions are pure.

import {
  DELTA_ADDED_EXISTS,
  DELTA_MODIFIED_MISSING,
  DELTA_REMOVED_MISSING,
  PURPOSE_DEFAULT,
  REQUIREMENT_NO_SCENARIO,
  REQUIREMENT_NO_STATEMENT,
} from "../prompts.ts";

export interface Requirement {
  readonly name: string;
  /** The whole block, from its heading to its last line, with no trailing blank line. */
  readonly text: string;
}

export interface Delta {
  readonly purpose: string | null;
  readonly added: Requirement[];
  readonly modified: Requirement[];
  readonly removed: string[];
}

const REQUIREMENT = /^### Requirement:\s*(.+?)\s*$/;
const SECTION = /^## (ADDED|MODIFIED|REMOVED) Requirements\s*$/;

/** The requirement blocks in `lines`. A block ends at the next heading of level 2 or 3. */
const blocks = (lines: readonly string[]): Requirement[] => {
  const out: Requirement[] = [];
  let cur: { name: string; lines: string[] } | null = null;
  const close = () => {
    if (cur) out.push({ name: cur.name, text: cur.lines.join("\n").trimEnd() });
    cur = null;
  };
  for (const line of lines) {
    const m = REQUIREMENT.exec(line);
    if (m) {
      close();
      cur = { name: m[1] ?? "", lines: [line] };
    } else if (/^#{2,3} /.test(line)) close();
    else cur?.lines.push(line);
  }
  close();
  return out;
};

/** The requirements of a spec text. */
export const parseRequirements = (text: string): Requirement[] =>
  blocks(text.split("\n"));

/** The text of the section `## Purpose` of `text`, or `null`. */
const purposeOf = (text: string): string | null => {
  const m = /^## Purpose\s*\n([\s\S]*?)(?=^## |(?![\s\S]))/m.exec(text);
  const body = m?.[1]?.trim();
  return body ? body : null;
};

/** The delta in `text`. A section that is absent is empty. */
export const parseDelta = (text: string): Delta => {
  const parts: Record<string, string[]> = {
    ADDED: [],
    MODIFIED: [],
    REMOVED: [],
  };
  let key: string | null = null;
  for (const line of text.split("\n")) {
    const m = SECTION.exec(line);
    if (m) key = m[1] ?? null;
    else if (/^## /.test(line)) key = null;
    if (key !== null) parts[key]?.push(line);
  }
  return {
    purpose: purposeOf(text),
    added: blocks(parts["ADDED"] ?? []),
    modified: blocks(parts["MODIFIED"] ?? []),
    removed: blocks(parts["REMOVED"] ?? []).map((r) => r.name),
  };
};

/**
 * The problems of the requirements of one spec or delta text: no statement text, and no scenario.
 * The check is structural. It reads the fixed labels of the format (`### Requirement:` and `#### Scenario:`) and no word of a language,
 * so a spec in any language is valid.
 */
export const requirementIssues = (reqs: readonly Requirement[]): string[] =>
  reqs.flatMap((r) => {
    const out: string[] = [];
    const statement = r.text
      .split("\n")
      .slice(1)
      .find((line) => line.trim() !== "");
    if (statement === undefined || statement.startsWith("#### Scenario:"))
      out.push(REQUIREMENT_NO_STATEMENT({ name: r.name }));
    if (!/^#### Scenario:/m.test(r.text))
      out.push(REQUIREMENT_NO_SCENARIO({ name: r.name }));
    return out;
  });

/** The text of a new spec for the capability `name`, with `purpose` and the requirement blocks. */
const render = (
  name: string,
  purpose: string,
  reqs: readonly Requirement[],
): string =>
  `# Spec: \`${name}\`\n\n## Purpose\n\n${purpose}\n\n## Requirements\n\n${reqs.map((r) => r.text).join("\n\n")}\n`;

/** The result of a merge: the new text of the spec, or the errors that stop the merge. */
export type Merged =
  | { ok: true; text: string }
  | { ok: false; errors: string[] };

/**
 * `delta` merged into `spec`, the current text of the spec of the capability `name` or `null` for a new spec.
 * ADDED needs a new name, and MODIFIED and REMOVED need a name that the spec has.
 */
export const mergeDelta = (
  name: string,
  spec: string | null,
  delta: Delta,
): Merged => {
  const reqs = spec === null ? [] : parseRequirements(spec);
  const names = new Set(reqs.map((r) => r.name));
  const errors: string[] = [];
  for (const r of delta.added)
    if (names.has(r.name))
      errors.push(DELTA_ADDED_EXISTS({ requirement: r.name, spec: name }));
  for (const r of delta.modified)
    if (!names.has(r.name))
      errors.push(DELTA_MODIFIED_MISSING({ requirement: r.name, spec: name }));
  for (const n of delta.removed)
    if (!names.has(n))
      errors.push(DELTA_REMOVED_MISSING({ requirement: n, spec: name }));
  if (errors.length > 0) return { ok: false, errors };
  const modified = new Map(delta.modified.map((r) => [r.name, r]));
  const kept = reqs
    .filter((r) => !delta.removed.includes(r.name))
    .map((r) => modified.get(r.name) ?? r);
  const purpose =
    (spec === null ? null : purposeOf(spec)) ??
    delta.purpose ??
    PURPOSE_DEFAULT({ name });
  return { ok: true, text: render(name, purpose, [...kept, ...delta.added]) };
};
